#!/bin/sh
# Generated by FWShift: a Google Cloud network firewall policy, created with gcloud. Read the report first: what is
# not written is listed there.
#
#   DRY_RUN=1 sh THIS_FILE                              prints the commands; needs no access to Google Cloud
#   GCLOUD_OPTS='--project my-project' sh THIS_FILE     creates the policy and its rules
#
# The policy is associated with no network: nothing changes for any traffic until you associate it:
#   gcloud compute network-firewall-policies associations create --firewall-policy fwshift --network NETWORK --global-firewall-policy
# It decides every connection of that network. Set the network's enforcement order to BEFORE_CLASSIC_FIREWALL, or
# the VPC firewall rules of the network decide first. A policy of the same name stops the script before anything is
# created; a command gcloud refuses stops it where it is (delete the policy and run it again).
set -u
DRY_RUN="${DRY_RUN:-}"
GCLOUD_OPTS="${GCLOUD_OPTS:-}"
POLICY=fwshift
fail() { printf 'FAILED: %s\n' "$*" >&2; exit 1; }
run() {
  if [ -n "$DRY_RUN" ]; then printf 'gcloud' >&2; printf ' %s' "$@" >&2; printf '\n' >&2; return 0; fi
  gcloud "$@" $GCLOUD_OPTS --quiet >/dev/null || fail "gcloud $1 $2 $3 $4"
}
if [ -z "$DRY_RUN" ] && gcloud compute network-firewall-policies describe "$POLICY" --global $GCLOUD_OPTS >/dev/null 2>&1; then
  fail "a network firewall policy named $POLICY exists already; nothing was created"
fi

run compute network-firewall-policies create "$POLICY" --global '--description=Generated by FWShift; review the conversion report before associating it'

run compute network-firewall-policies rules create 1000 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=192.168.10.50/31,192.168.10.52/30,192.168.10.56/30 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=nothing but TCP'
run compute network-firewall-policies rules create 1010 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=192.168.10.50/31,192.168.10.52/30,192.168.10.56/30 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=nothing but TCP'
run compute network-firewall-policies rules create 1020 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/1,128.0.0.0/2,192.0.0.0/9,192.128.0.0/11,192.160.0.0/13,192.168.0.0/21,192.168.8.0/23,192.168.10.0/27,192.168.10.32/28,192.168.10.48/31,192.168.10.60/30,192.168.10.64/26,192.168.10.128/25,192.168.11.0/24,192.168.12.0/22,192.168.16.0/20,192.168.32.0/19,192.168.64.0/18,192.168.128.0/17,192.169.0.0/16,192.170.0.0/15,192.172.0.0/14,192.176.0.0/12,192.192.0.0/10,193.0.0.0/8,194.0.0.0/7,196.0.0.0/6,200.0.0.0/5,208.0.0.0/4,224.0.0.0/3 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=nothing but TCP-2'
run compute network-firewall-policies rules create 1030 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/1,128.0.0.0/2,192.0.0.0/9,192.128.0.0/11,192.160.0.0/13,192.168.0.0/21,192.168.8.0/23,192.168.10.0/27,192.168.10.32/28,192.168.10.48/31,192.168.10.60/30,192.168.10.64/26,192.168.10.128/25,192.168.11.0/24,192.168.12.0/22,192.168.16.0/20,192.168.32.0/19,192.168.64.0/18,192.168.128.0/17,192.169.0.0/16,192.170.0.0/15,192.172.0.0/14,192.176.0.0/12,192.192.0.0/10,193.0.0.0/8,194.0.0.0/7,196.0.0.0/6,200.0.0.0/5,208.0.0.0/4,224.0.0.0/3 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=nothing but TCP-2'
run compute network-firewall-policies rules create 1040 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:80,tcp:443 '--description=no other web from guests'
run compute network-firewall-policies rules create 1050 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=tcp:80,tcp:443 '--description=no other web from guests'
run compute network-firewall-policies rules create 1060 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=no guests elsewhere'
run compute network-firewall-policies rules create 1070 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --enable-logging '--description=no guests elsewhere'
run compute network-firewall-policies rules create 1080 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=defconf: drop all from WAN not DSTNATed'
run compute network-firewall-policies rules create 1090 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all '--description=defconf: drop all from WAN not DSTNATed'
run compute network-firewall-policies rules create 1100 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=2001:db8:99::/48 --dest-ip-ranges=2001:db8:10::/64 --layer4-configs=tcp:443 '--description=the partners reach the web servers of the LAN by HTTPS and nothing else'
run compute network-firewall-policies rules create 1110 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=2001:db8:99::/48 --dest-ip-ranges=2001:db8:10::/64 --layer4-configs=tcp:443 '--description=the partners reach the web servers of the LAN by HTTPS and nothing else'
run compute network-firewall-policies rules create 1120 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all '--description=drop everything else not coming from LAN'
run compute network-firewall-policies rules create 1130 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=deny --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all '--description=drop everything else not coming from LAN'
run compute network-firewall-policies rules create 1140 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-allow
run compute network-firewall-policies rules create 1150 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=0.0.0.0/0 --dest-ip-ranges=0.0.0.0/0 --layer4-configs=all --description=fwshift-default-allow
run compute network-firewall-policies rules create 1160 --firewall-policy="$POLICY" --global-firewall-policy --direction=INGRESS --action=allow --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-allow
run compute network-firewall-policies rules create 1170 --firewall-policy="$POLICY" --global-firewall-policy --direction=EGRESS --action=allow --src-ip-ranges=::/0 --dest-ip-ranges=::/0 --layer4-configs=all --description=fwshift-default-allow

# Not written:
#   defconf: accept in ipsec policy: not converted: ipsec-policy=in,ipsec (traffic of IPsec tunnels)
#   banned scanners: not converted: address list 'scanners', which rules fill while the router runs
#   ssh from the admins: the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   web for everyone: the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   web for everyone-2: the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   ping "echo" only: the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   ping "echo" only-2: the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   old partner access: the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   old partner access-2: the destination of the rule is in zone DMZ, and a rule of Google Cloud names no zone: give the networks behind DMZ with --zone-network
#   rest of the DMZ: not converted: negated destination that does not name the same on both sides of NAT rule 'publish web' (203.0.113.3, 172.16.20.10); not converted: negated destination that does not name the same on both sides of NAT rule 'publish mail' (203.0.113.4, 172.16.20.11)
#   rest of the DMZ-2: not converted: negated destination that does not name the same on both sides of NAT rule 'publish web' (203.0.113.3, 172.16.20.10); not converted: negated destination that does not name the same on both sides of NAT rule 'publish mail' (203.0.113.4, 172.16.20.11)
#   rest of the DMZ-3: not converted: negated destination that does not name the same on both sides of NAT rule 'publish web' (203.0.113.3, 172.16.20.10); not converted: negated destination that does not name the same on both sides of NAT rule 'publish mail' (203.0.113.4, 172.16.20.11)
#   LAN to the package mirrors: the source of the rule is in zone LAN, and a rule of Google Cloud names no zone: give the networks behind LAN with --zone-network; the destination 'mirrors' holds members only its platform knows; a rule of Google Cloud names addresses
#   guest DNS, either port: the source of the rule is in zone GUEST, and a rule of Google Cloud names no zone: give the networks behind GUEST with --zone-network; the destination of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network
#   guest DNS, either port-2: the source of the rule is in zone GUEST, and a rule of Google Cloud names no zone: give the networks behind GUEST with --zone-network; the destination of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network
#   guests to the internet: the source of the rule is in zone GUEST, and a rule of Google Cloud names no zone: give the networks behind GUEST with --zone-network; the destination of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network
#   office hours for staff: schedule 'time=8h-18h,mon,tue,wed,thu,fri' is not converted; the rule would apply at all times; the source of the rule is in zone LAN, and a rule of Google Cloud names no zone: give the networks behind LAN with --zone-network; the destination of the rule is in zone WAN, and a rule of Google Cloud na
#   defconf: drop all from WAN not DSTNATed (allows publish web): the source of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network
#   defconf: drop all from WAN not DSTNATed (allows publish mail): the source of the rule is in zone WAN, and a rule of Google Cloud names no zone: give the networks behind WAN with --zone-network
#   ICMPv6 echo: what it allows cannot be said by a rule of Google Cloud

echo 'Done. Associate the policy with the network when you are ready; until then nothing changes.' >&2
